#include <stdio.h>

int max_of(int a[], int n) {
    int m = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] > m) {
            m = a[i];
        }
    }
    return m;
}

int main() {
    int a[5] = {3, 9, 2, 7, 5};
    printf("%d\n", max_of(a, 5));
    return 0;
}

