#include <stdio.h>

int count_char(char s[], char c) {
    int count = 0;
    return count;
}

int main() {
    printf("%d\n", count_char("banana", 'a'));
    return 0;
}

answer:
#include <stdio.h>

int count_char(char s[], char c) {
    int count = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == c) {
            count++;
        }
    }
    return count;
}

int main() {
    printf("%d\n", count_char("banana", 'a'));
    return 0;
}

