#include <stdio.h>

#include <string.h>

void print_reverse(char s[]) {
    printf("%s\n", s);
}

int main() {
    print_reverse("hello");
    return 0;
}

answer:
#include <stdio.h>

#include <string.h>

void print_reverse(char s[]) {
    int n = strlen(s);
    for (int i = n - 1; i >= 0; i--) {
        printf("%c", s[i]);
    }
    printf("\n");
}

int main() {
    print_reverse("hello");
    return 0;
}

